import * as duckdb from '@duckdb/duckdb-wasm';
import * as XLSX from 'xlsx';

let db: duckdb.AsyncDuckDB | null = null;

async function initDB() {
    if (db) return db;

    const JSDELIVR_BUNDLES = duckdb.getJsDelivrBundles();
    const bundle = await duckdb.selectBundle(JSDELIVR_BUNDLES);

    const worker_url = URL.createObjectURL(
        new Blob([`importScripts("${bundle.mainWorker!}");`], { type: 'text/javascript' })
    );

    const worker = new Worker(worker_url);
    const logger = new duckdb.ConsoleLogger();
    db = new duckdb.AsyncDuckDB(logger, worker);
    await db.instantiate(bundle.mainModule, bundle.pthreadWorker);
    URL.revokeObjectURL(worker_url);

    return db;
}

async function excelToCSV(file: File): Promise<string> {
    const data = await file.arrayBuffer();
    const workbook = XLSX.read(data, { type: 'array' });
    const firstSheetName = workbook.SheetNames[0];
    const worksheet = workbook.Sheets[firstSheetName];
    return XLSX.utils.sheet_to_csv(worksheet);
}

export async function profileFile(file: File) {
    const duckDB = await initDB();
    const conn = await duckDB.connect();

    try {
        const extension = file.name.split('.').pop()?.toLowerCase();
        const tableName = 'dataset';

        // Load data based on format
        if (extension === 'xlsx' || extension === 'xls') {
            const csvData = await excelToCSV(file);
            await duckDB.registerFileText('temp.csv', csvData);
            await conn.insertCSVFromPath('temp.csv', {
                name: tableName,
                header: true,
                detect: true,
            });
        } else if (extension === 'csv') {
            await duckDB.registerFileHandle(file.name, file, (duckdb.DuckDBDataProtocol as any).BROWSER_FILE, true);
            await conn.insertCSVFromPath(file.name, {
                name: tableName,
                header: true,
                detect: true,
            });
        } else if (extension === 'json') {
            await duckDB.registerFileHandle(file.name, file, (duckdb.DuckDBDataProtocol as any).BROWSER_FILE, true);
            await conn.query(`CREATE TABLE ${tableName} AS SELECT * FROM read_json_auto('${file.name}')`);
        }

        // Get table info
        const columnsResult = await conn.query(`DESCRIBE ${tableName}`);
        const columns = columnsResult.toArray().map((row: any) => ({
            name: row.column_name,
            type: row.column_type,
        }));

        // Get basic stats for each column
        const stats: any[] = [];
        for (const col of columns) {
            const colStats = await conn.query(`
        SELECT 
          MIN("${col.name}") as min,
          MAX("${col.name}") as max,
          COUNT(*) as total_count,
          COUNT("${col.name}") as non_null_count,
          COUNT(DISTINCT "${col.name}") as unique_count
        FROM ${tableName}
      `);

            const statsRow = colStats.toArray()[0];
            stats.push({
                column: col.name,
                type: col.type,
                min: statsRow.min,
                max: statsRow.max,
                total: Number(statsRow.total_count),
                nulls: Number(statsRow.total_count) - Number(statsRow.non_null_count),
                unique: Number(statsRow.unique_count),
            });
        }

        // Get sample data for preview
        const previewResult = await conn.query(`SELECT * FROM ${tableName} LIMIT 10`);
        const preview = previewResult.toArray().map((row: any) => {
            const plainRow: any = {};
            for (const key of Object.keys(row)) {
                plainRow[key] = typeof row[key] === 'bigint' ? Number(row[key]) : row[key];
            }
            return plainRow;
        });

        return { columns, stats, preview };
    } finally {
        await conn.close();
    }
}
